//! 🔋️ Actual Energy declaration admission against the shared language-neutral model corpus.
use crate::standards::v1::subsets::any::io::sqlite::snapshot::EnergyModelSnapshot;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits,SqliteValue}};

#[test]
fn sqlite_snapshot_energy_actual_owner_declares_capability(){
    let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    assert_eq!(corpus["modelCollections"].as_array().unwrap().len(),37);
    assert_eq!(corpus["scheduleCollections"].as_array().unwrap().len(),5);
    assert!(<EnergyModelSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().is_some(),"actual Energy owner is missing its relational capability");
}

#[test]
fn sqlite_snapshot_energy_typed_full_document_and_independent_edits(){
 let mut source=EnergyModelSnapshot::default();source.schema="custom\0🌍".into();source.model.name="full native root".into();source.model.zones=vec![crate::model::Zone{id:crate::model::EntityId(u32::MAX),name:"duplicate domain".into(),volume_m3:f64::from_bits(0x7ff8000000000042),multiplier:u32::MAX,conditioned:true,part_of_total_floor_area:false},crate::model::Zone{id:crate::model::EntityId(u32::MAX),name:"unresolved".into(),volume_m3:-0.0,multiplier:0,conditioned:false,part_of_total_floor_area:true}];
 let database=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(database.tables.len(),69);let reconstructed=EnergyModelSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(reconstructed.schema,source.schema);assert_eq!(reconstructed.model.zones[0].volume_m3.to_bits(),source.model.zones[0].volume_m3.to_bits());assert_eq!(reconstructed.model.zones[1].volume_m3.to_bits(),source.model.zones[1].volume_m3.to_bits());assert_eq!(reconstructed.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),database);
 let mut edited=database.clone();edited.table_mut("energy_zone").unwrap().rows[0].values[4]=SqliteValue::Text("edited entity".into());assert_eq!(EnergyModelSnapshot::from_sqlite_database(&edited,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().model.zones[0].name,"edited entity");
}

