#[test]
fn sqlite_snapshot_energy_four_copy_phases_have_real_interior_cancellation_and_limits(){
 use store::sqlite_snapshot::{SqliteSnapshotPhase as Phase,SnapshotEncoding};let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let large=corpus["controls"]["largeTextBytes"].as_u64().unwrap() as usize;let after=corpus["controls"]["cancelAfter"].as_u64().unwrap() as usize;let mut source=EnergyModelSnapshot::default();source.model.name="🌍".repeat(large);let db=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let rows=db.tables.iter().map(|t|t.rows.len()).sum();
 for phase in[Phase::ProjectSnapshot,Phase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{let stop=event.phase==phase&&event.total>after&&event.completed>=after&&event.completed<event.total;reached|=stop;!stop};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let result=if phase==Phase::ProjectSnapshot{source.to_sqlite_database(&mut control).map(|_|())}else{EnergyModelSnapshot::from_sqlite_database(&db,&mut control).map(|_|())};assert!(result.is_err()&&reached);}
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let length=match &payload{store::io_schema::IoPayload::Binary(v)=>v.len(),store::io_schema::IoPayload::Text(v)=>v.len()};assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,max_file_bytes:length,..SqliteDatabaseLimits::default()})).unwrap()==payload);let restored=EnergyModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:rows,..SqliteDatabaseLimits::default()})).unwrap();assert_eq!(restored.model.name,source.model.name);
 for phase in[Phase::EncodeNative,Phase::DecodeNative]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{let stop=event.phase==phase&&event.total>after&&event.completed>=after&&event.completed<event.total;reached|=stop;!stop};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let result=if phase==Phase::EncodeNative{source.encode_sqlite_snapshot_native(encoding,&mut control).map(|_|())}else{EnergyModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut control).map(|_|())};assert!(result.is_err()&&reached,"native interior stage {phase:?}");}
 for limits in[SqliteDatabaseLimits{max_rows:rows-1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:length-1,..SqliteDatabaseLimits::default()}]{assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(EnergyModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}
 assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(EnergyModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
}

#[test]
fn sqlite_snapshot_energy_duplicate_surrogates_dangling_ownership_and_weakened_schema_refuse(){
 let mut source=EnergyModelSnapshot::default();source.model.zones.push(crate::model::Zone{id:crate::model::EntityId(0),name:"z".into(),volume_m3:0.0,multiplier:0,conditioned:false,part_of_total_floor_area:false});let db=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let mut duplicate=db.clone();let mut row=duplicate.table("energy_zone").unwrap().rows[0].clone();row.values[2]=SqliteValue::Integer(1);duplicate.table_mut("energy_zone").unwrap().rows.push(row);assert!(EnergyModelSnapshot::from_sqlite_database(&duplicate,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());let mut dangling=db.clone();dangling.table_mut("energy_zone").unwrap().rows[0].values[1]=SqliteValue::Integer(2);assert!(EnergyModelSnapshot::from_sqlite_database(&dangling,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());let mut weakened=db;weakened.table_mut("energy_zone").unwrap().sql=weakened.table("energy_zone").unwrap().sql.replace("name TEXT NOT NULL","name TEXT");assert!(EnergyModelSnapshot::from_sqlite_database(&weakened,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());
}

fn full_energy_fixture()->EnergyModelSnapshot{let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut s=EnergyModelSnapshot::default();s.schema=corpus["schema"].as_str().unwrap().into();s.model=serde_json::from_value(corpus["completeModel"].clone()).unwrap();s.structure.target.dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio.value".into(),standard:"v1".into(),subset:"*".into()};s.zones.target.dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio.table".into(),standard:"v1".into(),subset:"*".into()};s.structure.child_id="local!\0🌍".into();s.structure.target.artifact_id="remote!\0🌍".into();s.zones.child_id="zones-alias".into();s.zones.target.artifact_id=String::new();s}
fn energy_project(s:&EnergyModelSnapshot)->store::sqlite_snapshot::SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
#[test]
fn sqlite_snapshot_energy_actual_bare_declared_both_native_encodings_and_exact_coordinate(){
 use store::sqlite_snapshot::SnapshotEncoding;let source=full_energy_fixture();let provider=store::ArtifactCodec::bare::<EnergyModelSnapshot,crate::EnergyModelMutation>(crate::ENERGY_MODEL_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<EnergyModelSnapshot>()));let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.energy.model".into(),standard:"1".into(),subset:"*".into()};
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let db=(provider.export)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(db,energy_project(&source));let back=(provider.import)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(back,payload);}
 for(kind,standard,subset)in[("s.energy.other","1","*"),("s.energy.model","v1","*"),("s.energy.model","1","named")]{let wrong=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:kind.into(),standard:standard.into(),subset:subset.into()};assert!(source.validate_sqlite_snapshot_subset(&wrong,&energy_project(&source),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_energy_actual_declaration_typed_physical_io(){
 use semio_framework_os_kernel::io::io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot};use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotPhase};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("energy").label("Energy SQLite owner").version("0.0.1").package_id("semio:energy").artifact(crate::declaration().unwrap()).try_build().unwrap();let source=full_energy_fixture();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.energy.model".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&source,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;let restored=io_import_sqlite_snapshot::<EnergyModelSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert_eq!(energy_project(&restored),energy_project(&source));assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}
}
#[test]
fn sqlite_snapshot_energy_independent_engine_edits_every_ieee_field_then_erased_roundtrips(){
 use std::io::Write;use std::process::{Command,Stdio};use store::sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding};let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let bytes=export_sqlite_database(&energy_project(&full_energy_fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let provider=store::ArtifactCodec::bare::<EnergyModelSnapshot,crate::EnergyModelMutation>(crate::ENERGY_MODEL_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.energy.model".into(),standard:"1".into(),subset:"*".into()};
 let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true}),bits=BigInt('0x'+process.env.SEMIO_TEST_WORD),signed=BigInt.asIntN(64,bits),b=new ArrayBuffer(8),v=new DataView(b);v.setBigUint64(0,bits);const number=v.getFloat64(0),kind=Number.isNaN(number)?'nan':number===Infinity?'positiveInfinity':number===-Infinity?'negativeInfinity':'finite';let count=0;for(const table of d.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){for(const column of d.query('PRAGMA table_info('+table.name+')').all()){if(column.type!=='REAL')continue;const c=column.name,n=Number(d.query('SELECT COUNT(*) AS n FROM '+table.name+' WHERE '+c+'_ieee754_bits IS NOT NULL').get().n);count+=n;d.query('UPDATE '+table.name+' SET '+c+'=?,'+c+'_ieee754_bits=?,'+c+'_ieee754_class=? WHERE '+c+'_ieee754_bits IS NOT NULL').run(Number.isNaN(number)?null:number,signed,kind);for(const row of d.query('SELECT '+c+'_ieee754_bits AS bits FROM '+table.name+' WHERE '+c+'_ieee754_bits IS NOT NULL').all())if(row.bits!==signed)throw Error('exact IEEE companion');}}if(count!==173)throw Error('all173 Energy words count '+count);if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";
 for word in corpus["binary64Words"].as_array().unwrap(){let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_TEST_WORD",word.as_str().unwrap()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let db=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let source=EnergyModelSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(energy_project(&source),db);energy_closed_extent(&source,word.as_str().unwrap());for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let exported=(provider.export)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(exported,db);assert_eq!((provider.import)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,exported,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}}
}
