fn sqlite_snapshot_energy_shared_negative_rows_refuse_all_native_widths_and_ownership(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let database=energy_project(&full_energy_fixture());for patch in corpus["malformedRows"].as_array().unwrap(){let mut bad=database.clone();let table=patch["table"].as_str().unwrap();let column=patch["column"].as_u64().unwrap() as usize;bad.table_mut(table).unwrap().rows[0].values[column]=match patch["storage"].as_str().unwrap(){"integer"=>SqliteValue::Integer(patch["value"].as_str().unwrap().parse().unwrap()),"real"=>SqliteValue::Real(patch["value"].as_str().unwrap().parse().unwrap()),_=>panic!("neutral malformed storage")};assert!(EnergyModelSnapshot::from_sqlite_database(&bad,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}/{column}");}}
#[test]
fn sqlite_snapshot_energy_all_literal_link_pin_variants_have_exact_unsigned64_native_io(){use store::sqlite_snapshot::SnapshotEncoding;let provider=store::ArtifactCodec::bare::<EnergyModelSnapshot,crate::EnergyModelMutation>(crate::ENERGY_MODEL_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.energy.model".into(),standard:"1".into(),subset:"*".into()};for pin in[store::LinkPin::Head,store::LinkPin::Checkpoint{id:"\0!@/🌍".into()},store::LinkPin::Snapshot{blob:store::BlobRef{hash:"h\0🌍".into(),size:u64::MAX,media_type:"m\0🌍".into()}}]{let mut s=full_energy_fixture();s.referenced_model=Some(store::ArtifactLink{target:semio_framework_artifact_reference::ArtifactRef{artifact_id:String::new(),dialect:dialect.clone()},pin,role:"role\0🌍".into()});s.weather_link=s.referenced_model.clone();let key=match &s.referenced_model.as_ref().unwrap().pin{store::LinkPin::Head=>"head",store::LinkPin::Checkpoint{..}=>"checkpoint",store::LinkPin::Snapshot{..}=>"snapshot"};energy_closed_extent(&s,key);let d=energy_project(&s);let restored=EnergyModelSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(restored.referenced_model,s.referenced_model);assert_eq!(restored.weather_link,s.weather_link);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let exported=(provider.export)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(exported,d);assert_eq!((provider.import)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,exported,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}}}

/// 📏️ Checks each closed full-domain extent through SQLite and both native ownership boundaries.
fn energy_closed_extent(source:&EnergyModelSnapshot,key:&str){
 use std::{io::Write,process::{Command,Stdio}};
 use store::sqlite_snapshot::{SnapshotEncoding,export_sqlite_database};
 let directory=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../🏅️standards/🔖️1/🪆️subsets/✳️any/🚪️io/🪶️sqlite/📸️snapshot/🧫️fixtures/📏️cells");
 let database=energy_project(source);
 let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let script=r#"import{Database}from'bun:sqlite';import{deepStrictEqual,ok}from'node:assert';
const fixture=await Bun.file(process.argv[1]).json(),key=process.argv[2];const expected=fixture.cases.find(c=>c.case===key);ok(expected);
const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});try{deepStrictEqual(db.query('PRAGMA integrity_check').get(),{integrity_check:'ok'});deepStrictEqual(db.query('PRAGMA foreign_key_check').all(),[]);const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(({name})=>{const expression=db.query('PRAGMA table_info('+name+')').all().map(({name})=>{const c='"'+name.replaceAll('"','""')+'"';return "CASE typeof("+c+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+c+" AS BLOB)) WHEN 'blob' THEN length("+c+") WHEN 'null' THEN 0 ELSE NULL END"}).join('+');const r=db.query('SELECT COUNT(*) AS rows,COALESCE(SUM('+expression+'),0) AS bytes FROM '+name).get();return{table:name,rows:Number(r.rows),semanticBytes:Number(r.bytes)}});deepStrictEqual(tables,expected.tables);deepStrictEqual({rows:tables.reduce((n,t)=>n+t.rows,0),semanticBytes:tables.reduce((n,t)=>n+t.semanticBytes,0)},{rows:expected.rows,semanticBytes:expected.semanticBytes});console.log(JSON.stringify({rows:expected.rows,semanticBytes:expected.semanticBytes}));}finally{db.close()}"#;
 let mut child=Command::new("bun").arg("-e").arg(script).arg(directory.join("🔣️.json")).arg(key).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
 child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
 let extent:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();let rows=extent["rows"].as_u64().unwrap()as usize;let cells=extent["semanticBytes"].as_u64().unwrap()as usize;
 let exact=SqliteDatabaseLimits{max_rows:rows,max_value_bytes:cells,..SqliteDatabaseLimits::default()};
 assert_eq!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),database);
 assert_eq!(energy_project(&EnergyModelSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap()),database);
 for refused in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{
  assert!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,refused)).is_err());
  assert!(EnergyModelSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,refused)).is_err());
 }
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();
  assert_eq!(energy_project(&EnergyModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap()),database);
  for refused in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{
   assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,refused)).is_err());
   assert!(EnergyModelSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,refused)).is_err());
  }
 }
}
#[test]
fn sqlite_snapshot_energy_closed_complete_semantic_extent(){
 let source=full_energy_fixture();energy_closed_extent(&source,"authored");
}
